import { cpSync, existsSync, mkdirSync, readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { emptyDir, removeDir, writeJson } from '@astrojs/internal-helpers/fs';
import {
	getTransformedRoutes,
	normalizeRoutes,
	type Route,
	type RouteWithSrc,
