		assetsDir: opts.settings.config.build.assets,
		routes,
		serverLike: opts.settings.buildOutput === 'server',
		middlewareMode,
		site: settings.config.site,
		base: settings.config.base,
		userAssetsBase: settings.config?.vite?.base,
